const InNeed = () => {
  const { lang } = useContext(LanguageContext);
  const { height, mobile, tablet, tabletLarge, desktopSmall } = useContext(
    ScreenModeAndSizeContext
  );
  const mobileDesktopClass = () => {
    return switchWindowSize(styles, mobile, tablet, tabletLarge, desktopSmall);
  };

  const getTitle = () => {
    if (mobile) {
      return TittleMobileSvg();
    } else if (tabletLarge) {
      return TitleTabletSvg();
    } else {
      return TitleSvg();
    }
  };

  return (
    <section
      style={{ maxHeight: height }}
      className={
        `${styles.section}` + " " + mobileDesktopClass() + " " + `section`
      }
    >
      <div className={styles.block}>
        <div className={`${styles.title} ` + " " + mobileDesktopClass()}>
          {getTitle()}
        </div>
        <div className={`${styles.text} h2`}>
          <h2>{InNeedText.paragraph[lang]}</h2>
        </div>
      </div>
    </section>
  );
};

export default InNeed;
